test('invoiceTotals includes voucher in calculation', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  }).value;

  const withVoucher = applyVoucher(invoice, { code: 'SAVE10', amount: 1000 }).value;
  const totals = invoiceTotals(withVoucher);
  const subtotal = 19000;
  const discountedAmount = subtotal;
  const vat = Math.round(discountedAmount * 21 / 100);
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, vat);
  assert.equal(totals.voucher, 1000);
  assert.equal(totals.total, subtotal + vat - 1000);
});

