  const r = applyVoucher(withVoucher, { code: 'EXTRA5', amount: 500 });
  assert.deepEqual(r, { ok: false, error: 'VOUCHER_EXISTS' });
});

test('applyVoucher rejects zero amount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  }).value;

