    lines: [{ sku: 'DEV-HOUR', qty: 2, discountPercent: 10 }],
  }).value;

  const withVoucher = applyVoucher(invoice, { code: 'SAVE5', amount: 500 }).value;
  const totals = invoiceTotals(withVoucher);
  const subtotal = 19000;
  const discount = Math.round(subtotal * 10 / 100);
  const discountedAmount = subtotal - discount;
  const vat = Math.round(discountedAmount * 21 / 100);
  const expectedTotal = subtotal - discount + vat - 500;
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, discount);
  assert.equal(totals.voucher, 500);
  assert.equal(totals.total, expectedTotal);
});

