});

test('addLine does not mutate the invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  }).value;

  const original = JSON.stringify(invoice);
  addLine(invoice, { sku: 'COPY-HOUR', qty: 3 });
