    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
      { sku: 'COPY-HOUR', qty: 2 },
    ],
  }).value;

  const r = removeLine(invoice, 'DEV-HOUR');
