  assert.equal(r.value.lines[0].sku, 'COPY-HOUR');
});

test('removeLine reports LINE_NOT_FOUND', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  }).value;

  const r = removeLine(invoice, 'NOPE');
