    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 10 }],
  }).value;

  const totals = invoiceTotals(invoice);
  const subtotal = 47500;
  const discount = 4750;
  const discountedAmount = 42750;
  const vat = Math.round(discountedAmount * 21 / 100);
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, discount);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, subtotal - discount + vat);
});

test('invoiceTotals sums discounts from multiple lines', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5, discountPercent: 10 },
      { sku: 'COPY-HOUR', qty: 3, discountPercent: 20 },
    ],
  }).value;

  const totals = invoiceTotals(invoice);
  const subtotal = 5 * 9500 + 3 * 6000;
  const discount = 4750 + 3600;
  const line1Discounted = 47500 - 4750;
  const line2Discounted = 18000 - 3600;
